function momentum(m, v){ return m*v; }
function impulse(F, t){ return F*t; }
function kineticEnergy(m, v){ return 0.5*m*v*v; }
function elastic1D(m1, v1, m2, v2){
  if(!(m1>0&&m2>0)) return null;
  var v1p = ((m1-m2)*v1 + 2*m2*v2)/(m1+m2);
  var v2p = ((m2-m1)*v2 + 2*m1*v1)/(m1+m2);
  return {v1:v1p, v2:v2p};
}
var EXPORTS = { momentum:momentum, impulse:impulse, kineticEnergy:kineticEnergy, elastic1D:elastic1D };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MomentumForgePure = EXPORTS; }
